  wireSay($("#cwZlOut"));
  $$("#cwZlOut .cw-cp").forEach(el => el.onclick = e => { if (e.target.closest("button,[lang]")) return; tap(el); st.cap = +el.dataset.c; $$("#cwZlOut .cw-cp").forEach(x => x.classList.toggle("on", x === el)); const cap = $("#cwZlCap"); cap.style.opacity = 0;
    setTimeout(() => { cap.textContent = z[tg][st.cap]; cap.style.opacity = 1; }, 200); buddy("zhoulan", T(["简单，干净。", "有故事了。", "这句我也想写。"][st.cap], ["Simple and clean.", "Now there's a story.", "I wish I'd written that."][st.cap])); });
