/* ───── 声音 ───── */
let AU = null;
const stopAu = () => { if (AU){ try { AU.pause(); } catch(e){} AU = null; } try { A().hush(); } catch(e){} };
function playBlob(b, btn){ stopAu(); const a = new Audio(URL.createObjectURL(b)); AU = a; if (btn) btn.classList.add("play"); a.onended = () => { if (btn) btn.classList.remove("play"); }; a.play().catch(() => { if (btn) btn.classList.remove("play"); }); }
async function playEntry(e, btn){ let r = null;
  if (e.act){ r = e.k ? await get("hv.actw", "rec", e.act + "|" + e.k) : null; } else r = await get("hv.jot", "rec", e.id);
  if (r && r.blob){ playBlob(r.blob, btn); return; }
  toast(T("这一笔的声音不在这台手机上", "That recording isn't on this phone")); }

/* ───── 送给世界：那一句 + 录音进 linevoices（现成的规则：要有录音、一条最多约 150KB）───── */
async function sendWorld(e, rec){ if (!rec || !rec.blob){ toast(T("这一笔的声音不在这台手机上，送不出去", "The recording isn't on this phone, so it can't be sent")); return null; }
  const b64 = await A().blobB64(rec.blob); if (!b64 || b64.length > 140000){ toast(T("这段录音太长了，说短一点再送", "That recording is too long — try a shorter take")); return null; }
  const id = await A().post("linevoices", {i: "jot:" + e.cat, k: wkOf(e), kind: "t", l: e.lg || SIDE(), nat: A().UI(), t: pl(e.l).slice(0, 300), heard: String(rec.heard || "").slice(0, 300), mime: rec.blob.type || "audio/webm", dur: rec.dur || 0, a: b64});
  if (!id){ const er = A().err(); toast(er && er.code === "login" ? T("登录以后才能送给世界，先替你留在手帐里了", "Log in to send it to the world — it's kept in your journal") : T("没送出去，再试一次？", "Couldn't send — try again?")); return null; }
  try { window.hvPx && window.hvPx({k: "gift", to: "world", from: "jot", cat: e.cat}); } catch(e2){}
  delete RV["jot:" + e.cat + "|" + wkOf(e)]; return id; }
function upd(id, f){ const o = ST(), e = o.e.find(x => x.id === id); if (!e) return null; f(e); SAVE(o); return e; }

