/* ── 我也试试：选一天 ── */
const SH = () => { let s = document.getElementById("fwSheet"); if (!s){ s = document.createElement("div"); s.id = "fwSheet"; s.className = "fwl-sheet"; s.dataset.nopy = ""; document.body.appendChild(s); const sc = document.createElement("div"); sc.id = "fwScrim"; sc.className = "fwl-scrim"; sc.dataset.fwl = "closesheet"; document.body.appendChild(sc); } return s; };
